scwin.vScrenID = "ULDINS16200.xml";
scwin.CPBO = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : CP / 전자단기사채 마스터  목록 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) == false) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SSTD_CD_GRNT_DD, edt_ESTD_CD_GRNT_DD) == false) {
        return false;
    }

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기 

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=STDCDCPBO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdcpbnd.select.listStdCdCpBoInquiry" + "&{P}STD_CD=" + txb_pSTD_CD.value + "&{P}ISU_NM=" + txb_pISU_NM.getValue() + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue() + "&{P}ACTIV_TP_CD=" + $c.stf.getObjectValue(cmb_pACTIV_YN) + "&{P}CP_BND_TP_CD=" + $c.stf.getObjectValue(cmb_CP_BND_TP_CD) + "&{P}SDATE=" + edt_SDATE.getValue() + "&{P}EDATE=" + edt_EDATE.getValue() + "&{P}SSTD_CD_GRNT_DD=" + edt_SSTD_CD_GRNT_DD.getValue() + "&{P}ESTD_CD_GRNT_DD=" + edt_ESTD_CD_GRNT_DD.getValue();

    //cmb_CP_BND_TP_CD
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};


/********************************************** 
 * 함수명   : ins_detail
 * 설명       : CP / 전자단기사채 마스터 상세 조회한다.
 ***********************************************/
scwin.ins_detail = function(STD_CD, FLAG) {
    // CP / 전자단기사채
    /* CP_BND_TP_CD
    03417	BO	전자단기사채
    03417	CP	CP채권*/
    var queryId = "";
    dts_detail.removeAll();
    dts_REQCDCPCDTVLU.removeAll();
    if (FLAG == "") return;
    if (FLAG == "CP") {
        queryId = "lds.ins.stdcdcpbnd.select.readStdCdCpCpBndInfoView"; // CP  마스터 상세  

    } else {
        queryId = "lds.ins.stdcdcpbnd.select.readStdCdCpBoBndInfoView"; // 전자단기사채  마스터 상세  

    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=STDCDCPBNDINFO_VIEW_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=" + queryId + "&{P}STD_CD=" + STD_CD;

    //  alert( url);

    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();

    // CP / 전자단기 사채 신용등급 
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=STDCDREQCDCPCDTVLU_VIEW_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdcpbnd.select.listBndCreditValu1" + "&{P}STD_CD=" + STD_CD;
    dts_REQCDCPCDTVLU.DataID = encodeURI(url);
    dts_REQCDCPCDTVLU.reset();
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 표준코드 OR 발행기관 코드      
    scwin.arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_setBoView
 * 설명       :  전자단기사채 상세화면을 정의한다.
 ***********************************************/
scwin.fn_setBoView = function(SIMSA_YN, LIST_STAT_CD) {
    if (LIST_STAT_CD == "N" && SIMSA_YN == "Y") {
        $c.win.alert(" 해당종목은 신규상장심사종목입니다. \n" + " 수정후에는 반드시 채권심사종목정보도 수정이 되도록 채권상장팀에 통보를 하셔야 됩니다.");
    } else if (LIST_STAT_CD == "Y") {
        //alert(" 상장채권은 수정할 수 없습니다. \n" + " 채권상장팀과 협의하시기 바랍니다.");
        btn_modify.setDisabled(true);
        btn_modify.src = "../img/ins/btn_modify_d.gif";
        btn_delete.setDisabled(true);
        btn_delete.src = "../img/ins/btn_delete_d.gif";

        // alert 삭제 및 비밀번호 초기화도 제어 추가 20140116
        btn_clearPwd.setDisabled(true);
        btn_clearPwd.src = "../img/ins/btn_clearPwd_d.gif";
    } else {
        btn_modify.setDisabled(false);
        btn_modify.src = "../img/ins/btn_modify.gif";
        btn_delete.setDisabled(false);
        btn_delete.src = "../img/ins/btn_delete.gif";
        btn_clearPwd.setDisabled(false);
        btn_clearPwd.src = "../img/ins/btn_clearPwd.gif";
    }
    if ($c.stf.getObjectValue(cmb_BND_TP_CD) == "AB") {
        if ($c.stf.getObjectValue(txb_BND_CLSS_CD) == "") {
            $c.win.alert("특수채 발행기관 코드가 없습니다.");
        }
    }
};





/********************************************** 
 * 함수명   : ins_remove
 * 설명       : CP/전자단기사채  삭제처리한다.
 ***********************************************/
scwin.ins_remove = function() {

    //dts_ListDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_ListDelete.insertRow();
    dts_ListDelete.setCellData(1, "STD_CD", txb_STD_CD.getValue());
    dts_ListDelete.setCellData(1, "ISU_NM", txb_ISU_NM.getValue());
    dts_ListDelete.setCellData(1, "CHG_RSN", txb_DEL_RSN.getValue());
    dts_ListDelete.setCellData(1, "UNQ_ISU_NM", txb_UNQ_ISU_NM.getValue());
    dts_ListDelete.setCellData(1, "ISUR_CD", txb_ISUR_CD.getValue());
    dts_ListDelete.setCellData(1, "ISU_DD", edt_ISU_DD.getValue());
    dts_ListDelete.setCellData(1, "MUNIBND_TP_CD", $c.stf.getObjectValue(cmb_MUNIBND_TP_CD));
    dts_ListDelete.setCellData(1, "BND_TP_CD", $c.stf.getObjectValue(cmb_BND_TP_CD));
    trs_remove.Action = "/StdCdCpBndInfoAction.do?method=removeStdCdCpBndInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&CP_BND_TP_CD=" + dts_detail.getCellData(dts_detail.getRowPosition(), "CP_BND_TP_CD");
    trs_remove.KeyName = "toinb_dataid4";
    trs_remove.KeyValue = "JSP(I:pInput=dts_ListDelete)";
    trs_remove.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_remove.Post();
};



/********************************************** 
 * 함수명   : ins_modify
 * 설명       : CP/전자단기사채  표준코드  수정한다.
 ***********************************************/
scwin.ins_modify = function() {
    dts_detail.setCellData(dts_detail.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    dts_REQCDCPCDTVLU.setCellData(dts_REQCDCPCDTVLU.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    trs_modify.Action = "/StdCdCpBndInfoAction.do?method=modifyStdCdCpBndInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&CP_BND_TP_CD=" + dts_detail.getCellData(dts_detail.getRowPosition(), "CP_BND_TP_CD");
    trs_modify.KeyName = "toinb_dataid4";
    trs_modify.KeyValue = "JSP(O:pReturnOut=dts_Rst,I:pInput=dts_detail,I:pInput1=dts_REQCDCPCDTVLU)";
    trs_modify.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_modify.Post();
};



/********************************************** 
 * 함수명   : fn_formCheck
 * 설명       : 폼을 체크한다.
 ***********************************************/
scwin.fn_formCheck = function() {
    if (txb_ISUR_CD.getValue() == "" || txb_ISUR_CD.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관코드"));
        txb_ISUR_CD.focus();
        return false;
    }
    if (txb_ISU_NM.getValue() == "" || txb_ISU_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글기준명"));
        txb_ISU_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 60, "한글기준명")) {
        txb_ISU_ABBRV.setValue("");
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (txb_ISU_ABBRV.getValue() == "" || txb_ISU_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글기준약명"));
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ABBRV, 20, "한글기준약명")) {
        txb_ISU_ABBRV.setValue("");
        txb_ISU_ABBRV.focus();
        return false;
    }
    if (txb_ISU_ENG_NM.getValue() == "" || txb_ISU_ENG_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 60, "영문종목명")) {
        txb_ISU_ENG_NM.setValue("");
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (txb_ISU_ENG_ABBRV.getValue() == "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 20, "영문종목약명")) {
        txb_ISU_ENG_ABBRV.setValue("");
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (txb_UNQ_ISU_NM.getValue() == "" || txb_UNQ_ISU_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글고유명"));
        txb_UNQ_ISU_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_UNQ_ISU_NM, 20, "한글고유명")) {
        txb_UNQ_ISU_NM.setValue("");
        txb_UNQ_ISU_NM.focus();
        return false;
    }
    if (txb_UNQ_ISU_ENG_NM.getValue() == "" || txb_UNQ_ISU_ENG_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문고유명"));
        txb_UNQ_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_UNQ_ISU_ENG_NM, 20, "영문고유명")) {
        txb_UNQ_ISU_ENG_NM.setValue("");
        txb_UNQ_ISU_ENG_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_ISU_DD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행일"));
        edt_ISU_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_EXP_DD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "상환일(만기일)"));
        edt_EXP_DD.focus();
        return false;
    }
    if (fn_CheckDateObj(edt_ISU_DD, "발행일")) return false;
    if (fn_CheckDateObj(edt_EXP_DD, "상환일(만기일)")) return false;
    if ($c.stf.getObjectValue(edt_YY1_BAS_YD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "이자율"));
        edt_YY1_BAS_YD.focus();
        return false;
    }
    /*if(getObjectValue(edt_DC_RT) == "" ) {
    	alert( getMessageParam("MSG-A005", "할인율") );
    	edt_DC_RT.focus();
    	return false;
    } */
    if ($c.stf.getObjectValue(edt_EXP_PAY_AMT) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "금액"));
        edt_EXP_PAY_AMT.focus();
        return false;
    }
    /*if(getObjectValue(edt_DC_SALES) == "" ) {
    	alert( getMessageParam("MSG-A005", "할인매출액") );
    	edt_DC_SALES.focus();
    	return false;
    } */
    if ($c.stf.getObjectValue(cmb_CURR_TP_CD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행통화"));
        cmb_CURR_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_DOM_FORN_ISU_TP_CD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행구분"));
        cmb_DOM_FORN_ISU_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_LIST_STAT_CD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "상장여부"));
        cmb_LIST_STAT_CD.focus();
        return false;
    }
    var CP_BND_TP_CD = dts_detail.getCellData(dts_detail.getRowPosition(), "CP_BND_TP_CD");
    if (CP_BND_TP_CD == "BO") {
        // 전자단기사채일경우 
        if ($c.stf.getObjectValue(cmb_BND_TP_CD) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "채권유형"));
            cmb_BND_TP_CD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_BND_CLSS_CD) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "채권분류코드"));
            txb_BND_CLSS_CD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_CFI_CD) == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI코드"));
            txb_CFI_CD.focus();
            return false;
        }
    }

    //CFI체크
    if ($c.stf.getObjectValue(cmb_cb_p_group) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_그룹"));
        cmb_cb_p_group.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_1) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_1차속성"));
        cmb_cb_p_attr_1.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_2) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_2차속성"));
        cmb_cb_p_attr_2.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_3) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_3차속성"));
        cmb_cb_p_attr_3.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_4) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_4차속성"));
        cmb_cb_p_attr_4.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) {
        //txb_ISU_ENG_ABBRV.value = "";
        txa_NUSUAL_ISU_COND_CONTN.focus();
        return false;
    }
};



/********************************************** 
 * 함수명   : fn_Change_cfi
 * 설명       : cfi 변경 설정 - 채권과 동일 .....
 ***********************************************/
scwin.fn_Change_cfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    var cfi = "";
    cfi = "D";
    if ($c.stf.getObjectValue(cmb_cb_p_group) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_group);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_1) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_1);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_2) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_2);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_3) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_3);
    if ($c.stf.getObjectValue(cmb_cb_p_attr_4) == "") cfi += "_";

    else cfi += $c.stf.getObjectValue(cmb_cb_p_attr_4);
    txb_CFI_CD.setValue(cfi); // cfi 설정

};


/********************************************** 
 * 함수명   : fn_set_Change
 * 설명       :  상세 조회시 CFI 상세 설정 
 ***********************************************/
scwin.fn_set_Change = function(str_cfi) {
    if (str_cfi == "") return;
    $c.stf.setObjectValue(cmb_cb_p_group, str_cfi.substring(1, 2));
    $c.stf.setObjectValue(cmb_cb_p_attr_1, str_cfi.substring(2, 3));
    $c.stf.setObjectValue(cmb_cb_p_attr_2, str_cfi.substring(3, 4));
    $c.stf.setObjectValue(cmb_cb_p_attr_3, str_cfi.substring(4, 5));
    $c.stf.setObjectValue(cmb_cb_p_attr_4, str_cfi.substring(5, 6));
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);

    //PanelToGroupBox(panel_3);
    //PanelToGroupBox(panel_5);
    //PanelToGroupBox(panel_6);

    //cfi콤보셋팅
    ins_cfi_set(dts_cfi_group, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "07", "D", "", "", "G");
    ins_combo_set(dts_CURR_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "02475", "SEL"); //02475 -통화구분 코드 
    ins_combo_set(dts_DOM_FORN_ISU_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03407", "SEL"); // 03407 - 국내해외  
    ins_combo_set(dts_BND_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "01422", "SEL"); // 01422 - 채권종목의 유형을 나타냄
    ins_combo_set(dts_MUNIBND_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03076", "SEL"); //03076 - 지방채구분코드 
