scwin.dts_detail_OnLoadCompleted = function(rowcount) {
    if (rowcount > 0) {
        var CFI_CD = dts_detail.getCellData(dts_detail.getRowPosition(), "CFI_CD");
        var SIMSA_YN = dts_detail.getCellData(dts_detail.getRowPosition(), "SIMSA_YN");
        var LIST_STAT_CD = dts_detail.getCellData(dts_detail.getRowPosition(), "LIST_STAT_CD");
        //set_Change("ECVTCN") ;
        scwin.fn_set_Change(CFI_CD);
        fn_CtrlBtn_temp("update");
        // 전자단기사채일경우에만  
        var STD_CD_APPL_ID = dts_detail.getCellData(dts_detail.getRowPosition(), "STD_CD_APPL_ID");
        var CP_BND_TP_CD = dts_detail.getCellData(dts_detail.getRowPosition(), "CP_BND_TP_CD");
        //alert(CP_BND_TP_CD);alert(dts_detail.NameValue(dts_detail.RowPosition,"EXP_PAY_AMT"));
        if (CP_BND_TP_CD == "BO") {
            scwin.fn_setBoView(SIMSA_YN, LIST_STAT_CD);
            $c.stf.showObj(panel_4, true);
            scwin.CPBO = "전자단기사채";
            txb_gubun.setValue("" + scwin.CPBO);
        } else {
            $c.stf.showObj(panel_4, false);
            scwin.CPBO = "CP";
            txb_gubun.setValue("" + scwin.CPBO);
        }
    } else {
        scwin.fn_set_Change("");
        fn_CtrlBtn_temp("no_data");
    }
};
